import re
from moler.cmd.commandtextualgeneric import CommandTextualGeneric
from moler.exceptions import CommandFailure
from moler.exceptions import ParsingDone


class Quadphy(CommandTextualGeneric):
    """Quadphy command class."""

    def __init__(self, connection, options, port_num, prompt=None, newline_chars=None, runner=None):
        """
        Get ASiR-ant port rate. Currently, only support options: "-c -p".

        :param connection: moler connection to device, terminal when command is executed
        :param options: Comandline opthions
        -h            display help
        -i            initialize(load firmware, configure, and notify systemd)
        -f            force master during init (default is prefer master)
        -s  5|10|b    advertise 5G, 10G, or both 5G/10G during init (default is 5G only)
        -c            check link status
        -p PORT_NUM   specify a single port to check or monitor (use with -c or -m)
        -[m|d]        can not run -m and -d at one time
                       -m: monitor link status and report changes
                       -d: start the dbus service for quadphys
        :param port_num: Which port rate in hub, index is from 0 to 11
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Quadphy, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                      runner=runner)

        self.port_num = port_num
        self.options = options

    def build_command_string(self):
        """
        Build command string.

        :return: String representation of command to send over connection to device.
        """
        return f"quadphy {self.options} {self.port_num}"

    def on_new_line(self, line, is_full_line):
        """
        Execute all parsing methods.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_command_error(line)
                self._parse_line(line)
            except ParsingDone:
                pass
        return super(Quadphy, self).on_new_line(line, is_full_line)

    # Usage: quadphy ACTION(S)
    _re_usage_info = re.compile(r"Usage:\squadphy\sACTION.*", re.I)

    def _parse_command_error(self, line):
        """
        Parse command error.

        :param line:
        :return:
        """
        if self._regex_helper.search_compiled(Quadphy._re_usage_info, line):
            self.set_exception(CommandFailure(self, "PORT is out of range"))
            raise ParsingDone

    # QPHY0 PORT0 (ANT0): copperLink:down copperSpeed:10G hostPcsLink:up usxgmiiAn:off usxgmiiAnBasePageLinkUp:no usxgmiiBasePage:0x1601
    _re_rate = re.compile(r"copperSpeed:(?P<RATE>.+)\shostPcsLink", re.I)

    def _parse_line(self, line):
        """
        Get the ant port rate from command result: 5G, 10G or 'autoneg in progress or disabled'.

        :param line: QPHY0 PORT0 (ANT0): copperLink:up copperSpeed:10G hostPcsLink:up usxgmiiAn:on usxgmiiAnBasePageLinkUp:yes usxgmiiBasePage:0xd601
        :return: None
        """
        if self._regex_helper.search_compiled(Quadphy._re_rate, line):
            self.current_ret = self._regex_helper.group("RATE")
        raise ParsingDone


